<?php

declare(strict_types=1);

namespace PDF\Syntax\Linearization;

use PDF\Serialization\SerializationContext;
use PDF\Syntax\Filters\Filter;
use PDF\Syntax\Object\StreamObject;

/** Distinct output stream identity; original generated bytes and encoding are preserved. */
final class ThumbnailStreamCopy extends StreamObject
{
    public function __construct(private readonly StreamObject $source, ThumbnailGraphCopies $copies)
    {
        parent::__construct(
            $source->data,
            new ThumbnailDictionaryCopy($source->dictionary(), $copies),
            ...array_map(static fn (Filter $filter): ThumbnailFilterCopy => new ThumbnailFilterCopy($filter, $copies), $source->filters)
        );
    }

    public function bytes(SerializationContext $context): string
    {
        return $this->source->bytes($context);
    }
}
